<?php require __DIR__.'/../lib/bootstrap.php';require_admin();$type=$_GET['type']??'orders';$eventId=(int)($_GET['event']??0);
header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition:attachment; filename="cactus-eventos-'.$type.'-'.date('Ymd-His').'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');
if($type==='vip'){fputcsv($out,['Evento','Data','Nome','Documento','E-mail','Telefone','Acompanhantes','Status'],';','\"','');$sql='SELECT v.*,e.title event_title,e.event_date FROM vip_entries v JOIN events e ON e.id=v.event_id WHERE 1=1';$args=[];if($eventId){$sql.=' AND v.event_id=?';$args[]=$eventId;}$sql.=' ORDER BY e.event_date,v.name';$st=db()->prepare($sql);$st->execute($args);foreach($st->fetchAll() as $r)fputcsv($out,[$r['event_title'],date_br($r['event_date']),$r['name'],$r['document'],$r['email'],$r['phone'],$r['companions'],status_label($r['status'])],';','\"','');}
else{fputcsv($out,['Pedido','Evento','Comprador','E-mail','Telefone','Documento','Total','Status','Pagamento','Criado em','Pago em'],';','\"','');$sql='SELECT o.*,e.title event_title FROM orders o JOIN events e ON e.id=o.event_id WHERE 1=1';$args=[];if($eventId){$sql.=' AND o.event_id=?';$args[]=$eventId;}$sql.=' ORDER BY o.id DESC';$st=db()->prepare($sql);$st->execute($args);foreach($st->fetchAll() as $r)fputcsv($out,[$r['order_number'],$r['event_title'],$r['buyer_name'],$r['buyer_email'],$r['buyer_phone'],$r['buyer_document'],number_format((float)$r['total'],2,',','.'),status_label($r['status']),$r['payment_mode'],dt_br($r['created_at']),dt_br($r['paid_at'])],';','\"','');}
fclose($out);audit_log('export.'.$type);exit;
